def sha(path):
    with Path(path).open('rb') as stream: return hashlib.file_digest(stream, 'sha256').hexdigest()

def main(supplement, name):
    spec = importlib.util.spec_from_file_location('accept125', Path(__file__).with_name('accept.py'))
    acceptance = importlib.util.module_from_spec(spec); spec.loader.exec_module(acceptance)
    more = json.loads(Path(supplement).read_bytes()); assert not set(ROWS) & set(more)
    rows = ROWS | {label:(item['path'], item['equal']) for label,item in more.items()}; assert set(rows) == acceptance.REQUIRED
    gates = {}
    for label,(relative,equal) in rows.items():
        path = ROOT / 'reports' / relative; report = json.loads(path.read_bytes()); assert report['passed'] is True, label
        assert len(equal) >= 2, label
        for field,expected in equal.items():
            actual = acceptance.extent_value(report, field); assert type(actual) is type(expected) and actual == expected, (label,field,actual,expected)
        gates[label] = dict(path=path.relative_to(ROOT).as_posix(), sha256=sha(path), equal=equal)
    out = ROOT / 'reports/m4-joint-startup125-root' / name; assert not out.exists()
    out.write_text(json.dumps(gates, indent=2)+'\n')
    print(json.dumps(dict(path=str(out), sha256=sha(out), gates=len(gates), predicates=sum(len(v['equal']) for v in gates.values()))))

if __name__ == '__main__': main(*sys.argv[1:])
